def valid_moves(word):
    def backtrack(i):
        if i == len(word) or len(set(word[i:])) == len(word):
            return 1
        else:
            for j in range(i, len(word)):
                if word[j] not in word[i:]:  # Check if adding current letter does not violate the rule
                    matched = backtrack(j + 1)  # Recurse
                else:
                    matched = 0
                matched %= MOD
                yield matched  # Yield to keep track of all valid moves
    return sum(backtrack(0)) % MOD

