from collections import deque

def swap_permutations(per1, per2):
    result = []
    for x, y in zip(per1, per2):
        if x != y:
            result.append((x, y))
    return result

def convert_sequences_taichi(A, B):
    a = list(A)
    b = list(B)

    n, m = len(B), len(A)
    result = float('inf')

    p1, p2 = [deque(a[0:x]) for x in range(1, n + 1)], [deque(b[0:y]) for y in range(1, n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            next_permutations = swap_permutations(p1[i-1], p2[j-1])
            for perm1, perm2 in next_permutations:
                new_p1, new_p2 = list(p1[i-1][perm1[1]:]), list(p2[j-1][perm2[1]:])
                for k in range(perm1[0] - 1):
                    new_p1 = deque(new_p1[k:]) + deque(new_p1[:k])
                    if k != 0:
                        break
                for k in range(perm2[0] - 1):
                    new_p2 = deque(new_p2[k:]) + deque(new_p2[:k])
                    if k != 0:
                        break
                result = min(result, i + j - 2 + len(per1) + len(per2) - len(new_p1) - len(new_p2) + len(next_permutations))

                if not new_p1:
                    break
            if not new_p2:
                break

    return result

