from typing import List
from collections import defaultdict

def mex(arr: List[int]) -> int:
    return next(iter(set(range(len(arr)) - {i for i in arr})))

def max_team_strength(n: int, students: List[int], clubs: List[int], d: int) -> List[int]:
    friends = [[] for _ in range(n + 1)]
    day_max_strength = [mex(clubs) for _ in range(d)]

    for day in range(d):
        choices = defaultdict(int)
        for i in range(1, n + 1):
            if len(friends[i]) == 0:
                choices[day_max_strength[day]] += 1
                day_max_strength[day] = mex(clubs)

        daily_max_strength = [mex(clubs) for _ in range(n)]
        for i in clubs:
            for j in range(n - 1, -1, -1):
                if i == clubs[j]:
                    break
                for ki in friends[i]:
                    friends[i].remove(ki)
                    daily_max_strength[ki] += 1
                    friends[clubs[j]].append(ki)
        for i in range(n):
            day_max_strength[i] = min(daily_max_strength[i], day_max_strength[i])

    return day_max_strength

