def factor(n, primes):
    """Compute the prime factors of n"""
    vector = []
    for p in primes:
        if n < p*p:
            break
        if p*p < n:
            for m in range(1, n//p + 1):
                vector.append(n // (p**m))
            break
        while n % p == 0:
            vector.append(n // p)
            n //= p
    vector.append(n)
    lengths = [1] * len(vector)
    for i in range(1, len(vector)):
        for j in range(i):
            if vector[i] % vector[j] == 0 and vector[i] // vector[j] < lengths[i-j] + lengths[j] + 1:
                lengths[i] = lengths[i-j] + lengths[j] + 1
                vector[i] = vector[i] // vector[j]
    factorization = []
    for i in range(len(vector)):
        if vector[i] == 1:
            for j in range(lengths[i]):
                factorization.append(vector[i-j])
            break
    return factorization

def inverse_modulo(a, m):
    """Compute the inverse modulo of a"""
    m0 = m
    y = 0
    x = 1
    if m == 1:
        return 0
    while a > 1:
        q = a // m
        t = m
        m = a % m
        a = t
        t = y
        y = x
        x = t - q * x
    if x < 0:
        x = x + m0
    result = power_modular(gcd(a, m0), m0-2, m0)
    return (result * a) % m0

def power_modular(x, n, m):
    """Compute a^b mod m using repeated squaring"""
    acc = 1
    while n > 0:
        if n & 1:
            acc = acc * x % m
        x = x * x % m
        n >>= 1
    return acc

