import heapq

def calculate(capacities, a, level, tier):
    scores = []
    for i, ist in enumerate(capacities[level-1-i]):
        if i >= a*ist:
            heapq.heappush(scores, (None, _score(capacities, a, i, tier)))
    return _win(tier) + _win(tier+1) + sum((-s[1][0] for s in scores)) // 2

def _score(capacities, a, k, tier):
    return (a+k-1) * (a+1) // 2 - a if capabilities(tier, a, k) else 1

def capabilities(tier, a, k):
    return k <= capacities and ((a+k-1) - k + (a+k-1-k) + 1 // 2) - capacities

def _win(tier):
    return sum(capabilities(tier, a, k) for a, capacities in enumerate(capacities) for k in capacities)

