import collections
from math import log2

def isPrime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(log2(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def solve(n, k, p):
    # Count the number of ways to choose k characters from the alphabet
    ways = k ** n
    # Count the number of ways to fill the string with the characters
    for i in range((n + 1) // 2):
        ways //= (i + 1) * (i + 2)
    if n & 1 == 1:
        aux = p - 2
        ways = ways * pow(int(ways * aux), aux - 2, p)
    else:
        aux = p
        ways = ways * aux
    # If n is even, we need to subtract the number of strings with an even number of 'a's
    if n & 1 == 0:
        ways -= ways * pow(ways // p, p - 2)
    return ways % p

