from collections import defaultdict

def assign_fare_zones(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    memo = {}

    def dfs(node, parent, known_order):
        if node in memo:
            return memo[node]
        order = [node] + [known_order[i] if not order else i for i, neig in enumerate(graph[node]) if not known_order] + known_order[::-1]
        order.sort()
        memo[node] = (len(order) - 1) // 2 + 1
        dfs_map = {u: len(dfs(i, node, [])) for i in (known_order if node < parent else known_order[1:len(order)])}
        for u, sz in dfs_map.items():
            i = order.index(u)
            memo[node] += sz + 1 if known_order else i
        return (memo[node], order)

    max_fare_zones = 0
    order = []
    for node in range(1, n + 1):
        _, known_order = dfs(node, 0, [])
        order = (known_order if node < parent else order[::-1])[:known_order.index(node)]
        if backtrack(order, memo[node], max_fare_zones):
            max_fare_zones = memo[node]

    order.sort()
    if max_fare_zones == n - 1:
        return max_fare_zones, order
    else:
        return -1

def backtrack(order, sz, max_fare_zones):
    s = sum([sz[i] - 1 if i == j else 0 for i in (0, 1, len(order)) for j in (i + 1, i, order.index(i)) - {-1}] + [1 if i == j-2 else 0 for i, j in enumerate(order) if not i == -1])
    i = order.index(i)
    return s == max_fare_zones
