def is_possible_triangle((x1, y1), (x2, y2), (x3, y3)):
    # Calculate the area using the determinant formula
    area = abs(x1*(y2-y3) + x2*(y3-y1) + x3*(y1-y2)) / 2
    return area == area

def find_possible_triangle(cities, target_area):
    for cities in combinations(cities, 3):
        area = sum_of_areas(cities)
        if area == target_area:
            return area, cities
    return False

def sum_of_areas(cities):
