class Tree:
    def __init__(self):
        self.roots = []
        self.points = defaultdict(set)

    def add_edge(self, u: int, v: int):
        branches = self.points[u] | self.points[v]
        for b in branches:
            self.points[v].remove(b)
            self.points[u].add(b)
        self.points[u].add(v)

    def calc_subtrees(self):
        sizes = [1] * len(self.roots)
        for i in range(len(self.roots)):
            self.recursive_size(self.roots[i])
            for lca_index in range((2 ** len(self.roots[i])) - 1, -1, -1):
                self.roots[i] = self.roots[lca_index] + self.roots[i] - self.roots[lca_index + 1]

    def recursive_size(self, vertex: int):
        root_pos = self.roots.index(vertex)
        size = 0
        for next_vertex in self.roots:
            size += self.roots[next_vertex]
            while next_vertex != -1 and next_vertex != vertex:
                size += self.roots[next_vertex]
                next_vertex = self.roots[next_vertex]

            self.roots[vertex] = next_vertex

        for each in self.roots:
            self.roots[each] = self.roots[each][int(len(self.roots[each]) / (2 ** len(self.roots) - 1))]
            self.points[each] = set(range(-1, -1 - len(self.roots[each]) + 2, -1))
        for lca_index in range(len(self.roots[root_pos]), (2 ** len(self.roots) - len(self.roots) + 1)):
            each = self.roots[lca_index]
            for pos in sizes[each - root_pos - 1]:
                self.roots[each] = self.roots[each][pos:pos + size].pop()
            self.roots[each] = size
            sizes[each - root_pos - 1] = [0] * (len(sizes[each - root_pos - 1]) + size - 1 + 4)

