    return False, None

def construct_tree(parents):
    counts = defaultdict(lambda: [float('inf'), False])
    navigation = defaultdict(lambda: [float('inf'), float('inf'), [], [float('inf'), []]])
    key = {}
    for vertex in range(1, len(parents) + 1):
        if 0 in navigation[vertex][1] or len(parents[vertex]) == 0:
            root, index = navigation[vertex]
            if index == navigation[vertex][0]:
                continue
        has_cycle := has_cycle(parents, defaultdict(int), vertex)
        counts[index][0] += has_cycle[1]
        counts[index][1] = True
    for vertex in range(1, len(parents) + 1):
        key[vertex] = max(counts[vertex][0], counts[vertex][1])
