from collections import defaultdict

def adjust_sequence(a, b, n):
    count = defaultdict(int)
    for i in range(n):
        c = b[a[i] - 1]
        if c == i + 1:
            count[i] += 1
    return count

def get_points_of_interest(r):
    return set(range(r))[::-1][:2*r-2][::-1]

def handle_p0(res, r):
    count = {i: 0 for i in range(r)}
    t = 5 * n
    for p in get_points_of_interest(r):
        if r % 2 == 0 and p <= (r//2 - 1):
            t = t - 1
            continue
        lo, hi = 1, t + 1
        while lo < hi:
            lo_idx = bisect.bisect_left(count, lo, hi + 1)
            if lo == lo_idx and lo_idx != hi + 1:
                res += (lo + 1) * (hi - lo)
            lo, hi = lo_idx, hi
            count[lo] -= 1
            count[hi] += 1
            count[hi + 1] += 1
            t -= r - p

    return res

def main():
