from itertools import product

def count_winning_words(n, k, mod):
    # Initialize DP table
    dp = [[0] * n for _ in range(k + 1)]
    for i in range(1, k + 1):
        # Skip the empty word
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for chars in product(chr(ord('A') + i - 1), repeat=2):
                val = 0
                for c in chars:
                    val *= 36
                    val += ord(c)
                if dp[j][i - 1] + val > mod or (dp[j][i-1]+val) % mod == 0:
                    dp[j][i] = (dp[j][i] + 1) % mod

    return dp[-1][-1]

