from collections import deque

def min_conversion_time(ti, td, tr, te, sequence_a, sequence_b):
    n = len(sequence_a)
    sequence_a += '_'
    sequence_b += '_'

    dp = [[[99999999, 99999999, 99999999, 99999999] for _ in range(n)] for _ in range(n)]

    for d in range(4):
        if d == 0:
            for i in range(n):
                dp[n-1][i][d] = min(dp[n-1][i][d], ti)
                dp[n][i][d] = min(dp[n][i][d], td)
        elif d == 1:
            for j in range(n):
                dp[j][n-1][d] = min(dp[j][n-1][d], td)
                dp[j][n][d] = min(dp[j][n][d], te)
        elif d == 2:
            for i in range(n-1):
                dp[i][i+1][d] = min(0, dp[i][i+1][d])
        elif d == 3:
            for i in range(n-1):
                for j in range(i+1, n):
                    dp[i][j][d] = min(dp[i][j][d], te)

    for i in range(n-3, -1, -1):
        for j in range(i+1, n):
            for d in range(4):
                if sequence_a[i] != sequence_b[j]:
                    for di in range(4):
                        if di != d:
                            dp[i][j][d] = min(dp[i][j][d], dp[i][j-1][di] + tr)
                if sequence_a[j] != sequence_b[i]:
                    for dj in range(4):
                        if dj != d:
                            dp[i][j][d] = min(dp[i][j][d], dp[i+1][j][dj] + tr)
                for di in range(4):
                    if di != d:
                        dp[i][j][d] = min(dp[i][j][d], dp[i][j-1][di] + td)
                        dp[i][j][d] = min(dp[i][j][d], dp[i+1][j][di] + td)
                        dp[i][j][d] = min(dp[i][j][d], dp[i][j+1][di] + tr + te)
                dp[i][j][d] = min(dp[i][j][d], dp[i+1][j-1][abs(d-j-i-1)] + tr)
                dp[i][j][d] = min(dp[i][j][d], dp[i-1][j-1][abs(d-j-i-1)] + td)

    return dp[0][len(sequence_a)-1][0]

