from math import gcd
from functools import reduce

# Define the function to calculate the greatest common divisor (GCD) recursively
def lcm(a, b):
    return a * b // gcd(a, b)

def find_gcd(A, partitions):
    if len(A) == 1:
        return A[0] % m
    lcm_value = reduce(lcm, A) % m

    def largest_divisor(D):
        largest_divider = 1
        for i in range(len(D)):
            div_value = D[i] % m
            larger_divisor = gcd(larger_divisor, div_value)
            if div_value != m and larger_divisor != 1:
                largest_divider = div_value
        return largest_divider

    total_gcd = A[partitions - 1]
    for i in range(partitions):
        smaller_gcd = A[i]
        if smaller_gcd != m:
            total_gcd = lcm_value * largest_divisor(smaller_gcd) % m
    return total_gcd

