from collections import defaultdict

def count_winning_words(n, k, p):
    MOD = 10**8 + 7
    dp = [0] * (1 << n)
    dp[0] = 1

    for i in range(n):
        new_dp = [0] * ((1 << n) + 1)
        for state in range((1 << n)):
            if state & (1 << i):
                new_dp[state] = (new_dp[state] + dp[state ^ (1 << i)]) % MOD
            else:
                for j in range(k):
                    if state & (1 << (i - 1)):
                        new_dp[state | (1 << (i - 1))] = (new_dp[state | (1 << (i - 1))] + dp[state]) % MOD
                    else:
                        new_dp[state | (1 << (i - 1))] = (new_dp[state | (1 << (i - 1))] + (1 << k - j) * dp[state]) % MOD
        dp = new_dp

    return dp[(1 << n) - 1]

